import torch
import torch.nn as nn
from torch.nn.modules.utils import _triple
from torch.utils.cpp_extension import load_inline
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>
#include <vector>
#define OC_TILE 24
// CTA spatial tile (cooperative): one CTA owns TD x TH x TW output voxels,
// stages the (haloed) input tile for the current input channel in shared
// memory so neighboring outputs reuse each input voxel instead of re-reading
// it from global memory. Threads in a CTA map to spatially adjacent outputs.
#define TW 16
#define TH 8
#define TD 2
// ------------------------- fallback direct kernel -------------------------
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int B, const int IC, const int OC,
    const int D, const int H, const int W,
    const int OD, const int OH, const int OW,
    const int KD, const int KH, const int KW,
    const int sD, const int sH, const int sW,
    const int pD, const int pH, const int pW,
    const int dD, const int dH, const int dW,
    const int groups,
    const bool has_bias)
{
    extern __shared__ float w_smem[];
    const int K = KD * KH * KW;
    const long gpos = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long total = (long)B * OD * OH * OW;
    const bool active = gpos < total;
    int b = 0, od = 0, oh = 0, ow = 0;
    if (active) {
        ow = (int)(gpos % OW);
        long t = gpos / OW;
        oh = (int)(t % OH); t /= OH;
        od = (int)(t % OD);
        b  = (int)(t / OD);
    }
    const int gOC = OC / groups;
    const int gIC = IC / groups;
    const long inPlane  = (long)D * H * W;
    const long outPlane = (long)OD * OH * OW;
    const bool unit_stride = (sD == 1) && (sH == 1) && (sW == 1);
    int grp[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) grp[i] = 0;
    for (int oc0 = 0; oc0 < OC; oc0 += OC_TILE) {
        float acc[OC_TILE];
        #pragma unroll
        for (int i = 0; i < OC_TILE; ++i) acc[i] = 0.f;
        if (groups > 1) {
            #pragma unroll
            for (int i = 0; i < OC_TILE; ++i) {
                int oc = oc0 + i;
                grp[i] = (oc < OC) ? (oc / gOC) : -1;
            }
        }
        for (int ic = 0; ic < IC; ++ic) {
            const int ic_grp = (groups > 1) ? (ic / gIC) : 0;
            for (int i = threadIdx.x; i < OC_TILE * K; i += blockDim.x) {
                int occ = i / K;
                int kk  = i - occ * K;
                int oc  = oc0 + occ;
                float wv = 0.f;
                if (oc < OC) {
                    int loc = oc - (oc / gOC) * gOC;
                    wv = weight[((long)ic * gOC + loc) * K + kk];
                }
                w_smem[i] = wv;
            }
            __syncthreads();
            if (active) {
                const float* in_base = input + ((long)b * IC + ic) * inPlane;
                for (int kd = 0; kd < KD; ++kd) {
                    int nd = od + pD - kd * dD;
                    int id;
                    if (unit_stride) {
                        if (nd < 0 || nd >= D) continue;
                        id = nd;
                    } else {
                        if (nd < 0 || (nd % sD) != 0) continue;
                        id = nd / sD;
                        if (id >= D) continue;
                    }
                    for (int kh = 0; kh < KH; ++kh) {
                        int nh = oh + pH - kh * dH;
                        int ih;
                        if (unit_stride) {
                            if (nh < 0 || nh >= H) continue;
                            ih = nh;
                        } else {
                            if (nh < 0 || (nh % sH) != 0) continue;
                            ih = nh / sH;
                            if (ih >= H) continue;
                        }
                        const float* in_row = in_base + ((long)id * H + ih) * W;
                        const int kk0 = (kd * KH + kh) * KW;
                        for (int kw = 0; kw < KW; ++kw) {
                            int nw = ow + pW - kw * dW;
                            int iw;
                            if (unit_stride) {
                                if (nw < 0 || nw >= W) continue;
                                iw = nw;
                            } else {
                                if (nw < 0 || (nw % sW) != 0) continue;
                                iw = nw / sW;
                                if (iw >= W) continue;
                            }
                            const float v = __ldg(in_row + iw);
                            const int kidx = kk0 + kw;
                            #pragma unroll
                            for (int occ = 0; occ < OC_TILE; ++occ) {
                                if (groups == 1 || grp[occ] == ic_grp) {
                                    acc[occ] += v * w_smem[occ * K + kidx];
                                }
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
        if (active) {
            const long out_base = ((long)b * OC) * outPlane
                                + ((long)od * OH + oh) * OW + ow;
            #pragma unroll
            for (int occ = 0; occ < OC_TILE; ++occ) {
                int oc = oc0 + occ;
                if (oc < OC) {
                    float val = acc[occ];
                    if (has_bias) val += __ldg(bias + oc);
                    output[out_base + (long)oc * outPlane] = val;
                }
            }
        }
    }
}
// ------------- cooperative CTA-tiled kernel (unit-stride fast path) -------
// Valid for groups==1, stride==1, dilation==1. Each CTA computes a
// TD x TH x TW tile of output voxels for one batch and loops over output
// channels in OC_TILE register blocks. For every input channel the haloed
// input tile (TD+KD-1) x (TH+KH-1) x (TW+KW-1) is staged once in shared
// memory and reused by all 256 outputs in the CTA (up to KD*KH*KW reuse),
// removing redundant global input fetches and all per-tap bounds branches.
__global__ void conv_transpose3d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int B, const int IC, const int OC,
    const int D, const int H, const int W,
    const int OD, const int OH, const int OW,
    const int KD, const int KH, const int KW,
    const int pD, const int pH, const int pW,
    const int TX, const int TY, const int TZ,
    const bool has_bias)
{
    extern __shared__ float smem[];
    const int K  = KD * KH * KW;
    const int SD = TD + KD - 1;
    const int SH = TH + KH - 1;
    const int SW = TW + KW - 1;
    const int SWP = SW + 1;
    const int inTileLogical = SD * SH * SW;
    const int inTile = SD * SH * SWP;
    const int stageFloats = inTile + OC_TILE * K;
    // decode CTA -> (b, tz, ty, tx)
    int cta = blockIdx.x;
    const int tx = cta % TX; cta /= TX;
    const int ty = cta % TY; cta /= TY;
    const int tz = cta % TZ;
    const int b  = cta / TZ;
    const int OD0 = tz * TD;
    const int OH0 = ty * TH;
    const int OW0 = tx * TW;
    const int tid = threadIdx.x;
    // Keep the high OC_TILE input-reuse blocking, but map one output voxel
    // per thread. Removing the second spatial accumulator reduces register
    // pressure (profile showed occupancy limited by registers) while a
    // 256-thread CTA still exactly covers TD x TH x TW = 256 outputs.
    const int wt = tid % TW;
    const int ht = (tid / TW) % TH;
    const int dt = tid / (TW * TH);
    const int od = OD0 + dt;
    const int oh = OH0 + ht;
    const int ow = OW0 + wt;
    const bool active = (od < OD) && (oh < OH) && (ow < OW);
    // haloed input tile origin (global), may be negative
    const int id0 = OD0 + pD - (KD - 1);
    const int ih0 = OH0 + pH - (KH - 1);
    const int iw0 = OW0 + pW - (KW - 1);
    const long inPlane  = (long)D * H * W;
    const long outPlane = (long)OD * OH * OW;
    for (int oc0 = 0; oc0 < OC; oc0 += OC_TILE) {
        float acc[OC_TILE];
        #pragma unroll
        for (int i = 0; i < OC_TILE; ++i) { acc[i] = 0.f; }
        // -------- pipelined double-buffered staging over input channels --------
        // Two shared-memory buffers alternate: while the FMA phase reads buffer
        // (ic & 1), the haloed input tile and weights for input channel ic + 1 are
        // staged into buffer ((ic + 1) & 1), overlapping global loads with compute
        // and requiring only one __syncthreads() per input channel.
        auto stage = [&](int c, int buf) {
            float* d_in = smem + buf * stageFloats;
            float* d_w  = d_in + inTile;
            const float* in_base = input + ((long)b * IC + c) * inPlane;
            for (int i = tid; i < inTileLogical; i += blockDim.x) {
                const int dz = i / (SH * SW);
                const int rem = i - dz * (SH * SW);
                const int hy = rem / SW;
                const int sx = rem - hy * SW;
                const int id = id0 + dz;
                const int ih = ih0 + hy;
                const int iw = iw0 + sx;
                float v = 0.f;
                if (id >= 0 && id < D && ih >= 0 && ih < H && iw >= 0 && iw < W) {
                    v = in_base[((long)id * H + ih) * W + iw];
                }
                d_in[(dz * SH + hy) * SWP + sx] = v;
            }
            for (int i = tid; i < OC_TILE * K; i += blockDim.x) {
                const int occ = i / K;
                const int kk  = i - occ * K;
                const int oc  = oc0 + occ;
                float wv = 0.f;
                if (oc < OC) wv = weight[((long)c * OC + oc) * K + kk];
                d_w[i] = wv;
            }
        };
        stage(0, 0);
        __syncthreads();
        for (int ic = 0; ic < IC; ++ic) {
            const int cur = (ic & 1) * stageFloats;
            const float* s_in = smem + cur;
            const float* s_w  = smem + cur + inTile;
            if (ic + 1 < IC) stage(ic + 1, (ic + 1) & 1);
            if (active) {
                for (int kd = 0; kd < KD; ++kd) {
                    const int dz = dt + (KD - 1) - kd;
                    for (int kh = 0; kh < KH; ++kh) {
                        const int hy = ht + (KH - 1) - kh;
                        const float* s_row = s_in + (dz * SH + hy) * SWP + wt + (KW - 1);
                        const int kk0 = (kd * KH + kh) * KW;
                        #pragma unroll
                        for (int kw = 0; kw < 8; ++kw) {
                            if (kw < KW) {
                                const float v = s_row[-kw];
                                const int kidx = kk0 + kw;
                                #pragma unroll
                                for (int occ = 0; occ < OC_TILE; ++occ) {
                                    acc[occ] += v * s_w[occ * K + kidx];
                                }
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
        if (active) {
            const long out_base = ((long)b * OC) * outPlane
                                + ((long)od * OH + oh) * OW + ow;
            #pragma unroll
            for (int occ = 0; occ < OC_TILE; ++occ) {
                const int oc = oc0 + occ;
                if (oc < OC) {
                    float val = acc[occ];
                    if (has_bias) val += __ldg(bias + oc);
                    output[out_base + (long)oc * outPlane] = val;
                }
            }
        }
    }
}
at::Tensor conv_transpose3d_forward(
    at::Tensor x,
    at::Tensor weight,
    at::Tensor bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    std::vector<int64_t> dilation,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "input must be 5D (B, IC, D, H, W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (IC, OC/groups, KD, KH, KW)");
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    const int B  = (int)xc.size(0);
    const int IC = (int)xc.size(1);
    const int D  = (int)xc.size(2);
    const int H  = (int)xc.size(3);
    const int W  = (int)xc.size(4);
    const int KD = (int)wc.size(2);
    const int KH = (int)wc.size(3);
    const int KW = (int)wc.size(4);
    const int OC = (int)(wc.size(1) * groups);
    const int sD = (int)stride[0], sH = (int)stride[1], sW = (int)stride[2];
    const int pD = (int)padding[0], pH = (int)padding[1], pW = (int)padding[2];
    const int oD = (int)output_padding[0], oH = (int)output_padding[1], oW = (int)output_padding[2];
    const int dD = (int)dilation[0], dH = (int)dilation[1], dW = (int)dilation[2];
    const int OD = (D - 1) * sD - 2 * pD + dD * (KD - 1) + oD + 1;
    const int OH = (H - 1) * sH - 2 * pH + dH * (KH - 1) + oH + 1;
    const int OW = (W - 1) * sW - 2 * pW + dW * (KW - 1) + oW + 1;
    auto out = at::empty({B, OC, OD, OH, OW}, xc.options());
    const long total = (long)B * OD * OH * OW;
    if (total == 0) return out;
    const bool has_bias = bias.defined() && bias.numel() > 0;
    at::Tensor bc;
    const float* bptr = nullptr;
    if (has_bias) {
        bc = bias.contiguous();
        bptr = bc.data_ptr<float>();
    }
    const bool fast_path = (groups == 1) &&
        (sD == 1 && sH == 1 && sW == 1) &&
        (dD == 1 && dH == 1 && dW == 1);
    if (fast_path) {
        const int SD = TD + KD - 1;
        const int SH = TH + KH - 1;
        const int SW = TW + KW - 1;
        const int SWP = SW + 1;
        const size_t smem_bytes =
            2 * ((size_t)SD * SH * SWP + (size_t)OC_TILE * KD * KH * KW) * sizeof(float);
        if (smem_bytes <= 200 * 1024) {
            const int TX = (OW + TW - 1) / TW;
            const int TY = (OH + TH - 1) / TH;
            const int TZ = (OD + TD - 1) / TD;
            const long ctas = (long)B * TZ * TY * TX;
            if (ctas > 0 && ctas < 2147483647L) {
                if (smem_bytes > 48 * 1024) {
                    cudaFuncSetAttribute(conv_transpose3d_tiled_kernel,
                                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                                         (int)smem_bytes);
                }
                conv_transpose3d_tiled_kernel<<<(unsigned int)ctas, 256, smem_bytes,
                    at::cuda::getCurrentCUDAStream()>>>(
                    xc.data_ptr<float>(),
                    wc.data_ptr<float>(),
                    bptr,
                    out.data_ptr<float>(),
                    B, IC, OC,
                    D, H, W,
                    OD, OH, OW,
                    KD, KH, KW,
                    pD, pH, pW,
                    TX, TY, TZ,
                    has_bias);
                C10_CUDA_KERNEL_LAUNCH_CHECK();
                return out;
            }
        }
    }
    const int block = 256;
    const unsigned int grid = (unsigned int)((total + block - 1) / block);
    const size_t smem_bytes = (size_t)OC_TILE * KD * KH * KW * sizeof(float);
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv_transpose3d_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)smem_bytes);
    }
    conv_transpose3d_kernel<<<grid, block, smem_bytes,
        at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        bptr,
        out.data_ptr<float>(),
        B, IC, OC,
        D, H, W,
        OD, OH, OW,
        KD, KH, KW,
        sD, sH, sW,
        pD, pH, pW,
        dD, dH, dW,
        (int)groups,
        has_bias);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
