__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int B, const int IC, const int OC,
    const int D, const int H, const int W,
    const int OD, const int OH, const int OW,
    const int KD, const int KH, const int KW,
    const int sD, const int sH, const int sW,
    const int pD, const int pH, const int pW,
    const int dD, const int dH, const int dW,
    const int groups,
    const bool has_bias)
{
    extern __shared__ float w_smem[];
    const int K = KD * KH * KW;
    const long gpos = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long total = (long)B * OD * OH * OW;
    const bool active = gpos < total;
    int b = 0, od = 0, oh = 0, ow = 0;
    if (active) {
        ow = (int)(gpos % OW);
        long t = gpos / OW;
        oh = (int)(t % OH); t /= OH;
        od = (int)(t % OD);
        b  = (int)(t / OD);
    }
    const int gOC = OC / groups;
    const int gIC = IC / groups;
    const long inPlane  = (long)D * H * W;
    const long outPlane = (long)OD * OH * OW;
    const bool unit_stride = (sD == 1) && (sH == 1) && (sW == 1);
    int grp[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) grp[i] = 0;
    for (int oc0 = 0; oc0 < OC; oc0 += OC_TILE) {
        float acc[OC_TILE];
        #pragma unroll
        for (int i = 0; i < OC_TILE; ++i) acc[i] = 0.f;
        if (groups > 1) {
            #pragma unroll
            for (int i = 0; i < OC_TILE; ++i) {
                int oc = oc0 + i;
                grp[i] = (oc < OC) ? (oc / gOC) : -1;
            }
        }
        for (int ic = 0; ic < IC; ++ic) {
            const int ic_grp = (groups > 1) ? (ic / gIC) : 0;
            for (int i = threadIdx.x; i < OC_TILE * K; i += blockDim.x) {
                int occ = i / K;
                int kk  = i - occ * K;
                int oc  = oc0 + occ;
                float wv = 0.f;
                if (oc < OC) {
                    int loc = oc - (oc / gOC) * gOC;
                    wv = weight[((long)ic * gOC + loc) * K + kk];
                }
                w_smem[i] = wv;
            }
            __syncthreads();
            if (active) {
                const float* in_base = input + ((long)b * IC + ic) * inPlane;
                for (int kd = 0; kd < KD; ++kd) {
                    int nd = od + pD - kd * dD;
                    int id;
                    if (unit_stride) {
                        if (nd < 0 || nd >= D) continue;
                        id = nd;
                    } else {
                        if (nd < 0 || (nd % sD) != 0) continue;
                        id = nd / sD;
                        if (id >= D) continue;
                    }
                    for (int kh = 0; kh < KH; ++kh) {
                        int nh = oh + pH - kh * dH;
                        int ih;
                        if (unit_stride) {
                            if (nh < 0 || nh >= H) continue;
                            ih = nh;
                        } else {
                            if (nh < 0 || (nh % sH) != 0) continue;
                            ih = nh / sH;
                            if (ih >= H) continue;
                        }
                        const float* in_row = in_base + ((long)id * H + ih) * W;
                        const int kk0 = (kd * KH + kh) * KW;
                        for (int kw = 0; kw < KW; ++kw) {
                            int nw = ow + pW - kw * dW;
                            int iw;
                            if (unit_stride) {
                                if (nw < 0 || nw >= W) continue;
                                iw = nw;
                            } else {
                                if (nw < 0 || (nw % sW) != 0) continue;
                                iw = nw / sW;
                                if (iw >= W) continue;
                            }
                            const float v = __ldg(in_row + iw);
                            const int kidx = kk0 + kw;
                            #pragma unroll
                            for (int occ = 0; occ < OC_TILE; ++occ) {
