class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a custom CUDA kernel.
    Parameters are stored in an nn.ConvTranspose3d module (identical layout
    and initialization to the reference), while all computation in forward()
    is performed by the custom fused CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, _triple(kernel_size),
            stride=stride, padding=padding, output_padding=output_padding,
            dilation=dilation, groups=groups, bias=bias)
